package com.aistock.scheduler.adminrefresh;
import com.aistock.common.BusinessException;import com.aistock.common.adminrefresh.AdminMarketRefreshRecords.*;import com.aistock.scheduler.task.TaskRepository;
import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static com.aistock.scheduler.adminrefresh.RefreshTestDb.*;
@Tag("mysql") class AdminMarketRefreshMysqlTest {
 @Test void atomicCreateReplayAndConflict(){var f=new RefreshTestDb();var repo=f.repo();var c=command();var first=repo.submit(ACTOR,"SH600030",c,context(),NOW);assertEquals("QUEUED",first.receipt().outcome());assertEquals(1,f.count("scheduled_task"));assertEquals(1,f.count("admin_market_refresh_context"));assertEquals(1,f.count("admin_market_refresh_operation"));assertEquals(1,f.count("admin_market_refresh_guard"));var replay=repo.submit(ACTOR,"SH600030",c,context(),NOW.plusSeconds(1));assertTrue(replay.receipt().replayed());assertEquals(first.receipt().taskId(),replay.receipt().taskId());assertThrows(BusinessException.class,()->repo.submit(UUID.randomUUID(),"SH600030",c,context(),NOW));assertThrows(BusinessException.class,()->repo.submit(ACTOR,"SZ000002",c,context(),NOW));assertEquals(1,f.count("scheduled_task"));}
 @Test void concurrentSameStockAttachesRatherThanCreatingTwice()throws Exception{var f=new RefreshTestDb();var repo=f.repo();var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->repo.submit(ACTOR,"SH600030",command(),context(),NOW));var b=pool.submit(()->repo.submit(UUID.randomUUID(),"SH600030",command(),context(),NOW));assertEquals(Set.of("QUEUED","ATTACHED"),Set.of(a.get().receipt().outcome(),b.get().receipt().outcome()));assertEquals(1,f.count("scheduled_task"));assertEquals(2,f.count("admin_market_refresh_operation"));}finally{pool.shutdownNow();}}
 @Test void differentActiveTargetAndCooldownArePersistedRejections(){var f=new RefreshTestDb();var repo=f.repo();var a=repo.submit(ACTOR,"SH600030",command(),context(),NOW);var c=command();var different=new Command(c.operationId(),c.baseVersionId(),c.expectedHeadRevision(),java.time.LocalDate.parse("2026-10-26"),c.reasonCode());assertEquals("ACTIVE_REFRESH_EXISTS",repo.submit(ACTOR,"SH600030",different,context(),NOW).code());f.jdbc.update("update scheduled_task set state='FAILED',error_code='SOURCE_TIMEOUT' where task_id=?",a.receipt().taskId());assertEquals("REFRESH_COOLDOWN",repo.submit(ACTOR,"SH600030",command(),context(),NOW.plusSeconds(59)).code());assertEquals("QUEUED",repo.submit(ACTOR,"SH600030",command(),context(),NOW.plusSeconds(60)).receipt().outcome());}
 @Test void disabledFlagsRejectNewButDoNotPreventReplay(){var f=new RefreshTestDb();var cmd=command();var original=f.repo().submit(ACTOR,"SH600030",cmd,context(),NOW);var closed=new AdminMarketRefreshRepository(f.jdbc,false,false,60);assertTrue(closed.submit(ACTOR,"SH600030",cmd,context(),NOW).receipt().replayed());assertEquals("REFRESH_ACTIONS_DISABLED",closed.submit(ACTOR,"SH600030",command(),context(),NOW).code());assertEquals(original.receipt().taskId(),closed.receipt(cmd.operationId(),NOW).task().taskId());}
 @Test void contextInsertFailureRollsBackAllFourRecords(){var f=new RefreshTestDb();f.jdbc.execute("create trigger fixture_refresh_fail before insert on admin_market_refresh_context for each row signal sqlstate '45000' set message_text='fixture rollback'");try{assertThrows(BusinessException.class,()->f.repo().submit(ACTOR,"SH600030",command(),context(),NOW));assertEquals(0,f.count("scheduled_task"));assertEquals(0,f.count("admin_market_refresh_guard"));assertEquals(0,f.count("admin_market_refresh_operation"));}finally{f.jdbc.execute("drop trigger fixture_refresh_fail");}}
 @Test void historyStableUpperBoundAndGetNeverMutates(){var f=new RefreshTestDb();var repo=f.repo();for(int i=0;i<4;i++)repo.submit(ACTOR,"SH600030",command(),context(),NOW);var first=repo.history("SH600030",new HistoryQuery(null,2),NOW);assertEquals(2,first.items().size());assertTrue(first.hasMore());repo.submit(ACTOR,"SH600030",command(),context(),NOW.plusSeconds(1));var next=repo.history("SH600030",new HistoryQuery(first.nextCursor(),2),NOW);assertEquals(2,next.items().size());assertFalse(next.hasMore());assertNotEquals(first.items().get(0).receipt().operationId(),next.items().get(0).receipt().operationId());assertEquals(5,f.count("admin_market_refresh_operation"));}
 @Test void genericTaskCreationCannotForgeAdminPrefix(){var f=new RefreshTestDb();assertThrows(BusinessException.class,()->new TaskRepository(f.jdbc).create("SH600030",java.time.LocalDate.parse("2026-10-27"),"admin-market-refresh-"+UUID.randomUUID(),NOW));}
 @Test void workerRejectsMissingContextWithoutCallingMarket(){var f=new RefreshTestDb();var submitted=f.repo().submit(ACTOR,"SH600030",command(),context(),NOW);f.jdbc.update("delete from admin_market_refresh_context");var tasks=new TaskRepository(f.jdbc);var market=org.mockito.Mockito.mock(com.aistock.scheduler.task.MarketRefreshClient.class);var receipts=org.mockito.Mockito.mock(com.aistock.scheduler.task.MarketReceiptClient.class);var predictions=org.mockito.Mockito.mock(com.aistock.scheduler.task.PredictionTaskClient.class);new com.aistock.scheduler.task.TaskWorker(tasks,market,receipts,predictions,null,java.time.Clock.fixed(NOW,java.time.ZoneOffset.UTC),"fixture",false,false).runOnce();assertEquals("ADMIN_REFRESH_CONTEXT_INVALID",tasks.get(submitted.receipt().taskId()).errorCode());org.mockito.Mockito.verifyNoInteractions(market,receipts,predictions);}}